const JOBSTEPS={recognition:['冻结当前图纸版本','读取当前楼层预设候选','显示框选结果，等待复核'],generation:['冻结原图与标注版本','模拟构件几何构建','模拟二维图纸导出','模拟三维模型导出','模拟回读与成果审阅']};
function startJob(kind){if(job)return;if(kind==='recognition'&&p().versions.length>=limits.versions){toast('版本已达上限，请导出后另建项目。',true);return}const pr=p();job={id:uid('run'),projectId:pr.id,floorId:activeFloor,baseRevision:head().id,kind,index:0,created:now(),status:'running',modelExecuted:false,bimfaceConnected:false,stages:[...JOBSTEPS[kind]]};pr.runs.push(job);taskExpanded=true;event(pr,'demo.started',kind==='recognition'?'启动识别演示':'启动生成流程演示',{run:job.id,base:job.baseRevision,modelExecuted:false});$('resultRibbon').classList.add('hidden');updateUI();jobTimer=setInterval(tickJob,kind==='recognition'?850:1000)}
function tickJob(){if(!job)return;job.index++;if(job.index<job.stages.length){renderTask();if(screen==='home')renderHome();saveSoon();return}clearInterval(jobTimer);jobTimer=null;const j=job,pr=state.projects.find(x=>x.id===j.projectId);j.status='completed';j.finished=now();job=null;if(j.kind==='recognition'){if(head(pr).id===j.baseRevision){const f=head(pr).floors[j.floorId],a=pr.assets[f.assetId];if(a.sample){const n=Number(j.floorId.replace('F',''))||1;const items=clone(f.items);for(const o of presetItems(n)){if(!items.some(v=>v.id===o.id))items.push(o)}const prev=head(pr);pr.undo.push(prev.id);pr.redo=[];const next={id:'r'+pr.versions.length,parent:prev.id,title:'载入 '+f.label+' 预设识别候选',created:now(),floors:clone(prev.floors)};next.floors[j.floorId].items=items;pr.versions.push(next);invalidateResult(pr)}}event(pr,'recognition.demo.completed','识别演示结束',{run:j.id,modelExecuted:false});if(pr.id===activeId){updateUI();queueDraw();toast('预设候选已显示。点击琥珀色楼梯框，复核后保存。')}}else{const valid=head(pr).id===j.baseRevision;const result={id:uid('preview'),runId:j.id,revision:j.baseRevision,created:now(),stale:!valid,pending:Object.values(head(pr).floors).flatMap(f=>f.items).filter(o=>o.status==='pending').length,status:'DEMO_ONLY',architectureFilesCreated:false};pr.results.push(result);event(pr,'generation.demo.completed','生成流程演示结束',{result:result.id,revision:result.revision,modelExecuted:false,actualFiles:false});if(pr.id===activeId){updateUI();showResultRibbon(result);toast('流程演示完成。可预览标注与预设空间，未生成工程文件。')}}renderTask();if(screen==='home')renderHome();saveSoon()}
function renderTask(){const dock=$('taskDock');if(!job||screen!=='workspace'||job.projectId!==activeId){dock.classList.add('hidden');return}dock.classList.remove('hidden');const pct=Math.round(job.index/job.stages.length*100);dock.innerHTML=`<div class="task-head"><span class="spinner"></span><div><strong>${job.stages[job.index]}</strong><small>流程演示 · ${job.index+1} / ${job.stages.length} 阶段 · 非模型推理</small></div><button class="iconbtn" id="toggleTask" aria-label="${taskExpanded?'收起':'展开'}进度详情" title="${taskExpanded?'收起':'展开'}详情">${ic(taskExpanded?'minus':'plus')}</button></div><div class="task-track"><span style="width:${pct}%"></span></div>${taskExpanded?`<div class="task-details">${job.stages.map((s,i)=>`<div class="task-row ${i<job.index?'done':i===job.index?'running':''}"><i>${i<job.index?'✓':i+1}</i><span>${s}</span><small>${i<job.index?'演示完成':i===job.index?'演示中':'等待'}</small></div>`).join('')}<div class="task-bottom"><span>基于 ${job.baseRevision} · 当前标注暂时锁定</span><button class="textbtn" id="cancelTask">取消演示</button></div><div class="task-note">进度由本页定时演示；不是模型耗时或输出能力。</div></div>`:''}`;$('toggleTask').onclick=()=>{taskExpanded=!taskExpanded;renderTask()};if($('cancelTask'))$('cancelTask').onclick=cancelJob}
function cancelJob(){if(!job)return;clearInterval(jobTimer);const j=job,pr=state.projects.find(x=>x.id===j.projectId);j.status='cancelled';j.finished=now();job=null;event(pr,'demo.cancelled','取消流程演示，版本不变',{run:j.id,revision:j.baseRevision,modelExecuted:false});updateUI();renderTask();toast('已取消。本次请求保留在过程记录中。')}
function latestResult(){return p()?.results.slice().reverse().find(r=>r.revision===head().id&&!r.stale)}
function showResultRibbon(r){if(!r||r.stale)return;$('resultRibbon').innerHTML=`${ic('check')}<div><strong>${r.pending?'待复核的演示预览':'流程演示已完成'}</strong><small>${r.revision} · 尚未生成 DXF / PDF / GLB</small></div><button class="btn primary" id="previewResult">打开审阅 ${ic('arrow')}</button><button class="iconbtn" id="dismissResult" aria-label="收起结果提示">${ic('close')}</button>`;$('resultRibbon').classList.remove('hidden');$('previewResult').onclick=openResults;$('dismissResult').onclick=()=>$('resultRibbon').classList.add('hidden')}
function openResults(){guardDraft(()=>{const r=latestResult();if(!r){modal('还没有这一版的成果','先复核标注，再进入生成流程。',`<div class="notice">${p()?.results.length?'图纸或标注更新后，旧演示结果已过期。请重新生成，不混用历史版本。':'当前原型不连接模型。生成按钮演示阶段进度与结果审阅，不输出工程文件。'}</div>`,`<button class="btn" data-close>返回画布</button><button class="btn primary" id="fromResultGenerate">去生成确认</button>`);$('fromResultGenerate').onclick=()=>{closeModal();preflight()};return}const sample=Object.values(head().floors).every(f=>p().assets[f.assetId].sample);modal('成果审阅 · '+r.revision,'流程演示完成，真实交付能力尚未接入。',`<div class="review-floor"><b>二维复核</b><span>原图 + 当前标注，可实际查看</span></div><div class="review-floor"><b>三维预览</b><span>${sample?'预设空间示意，可拖动旋转':'未重建，不套用示例模型'}</span></div><div class="review-floor"><b>BIMFACE</b><span>未连接，无任何上传</span></div><div class="notice amber" style="margin-top:16px">${sample?'空间由人工预设几何绘制，不是从原图或新标注重建。':'本地导入图片只完成标注，识图与建模尚未运行。'}真实尺度、层高与工程检查仍未确认。</div><div class="flex" style="margin-top:17px;gap:8px"><button class="btn" disabled>下载 DXF</button><button class="btn" disabled>下载 PDF</button><button class="btn" disabled>下载 GLB</button></div><p class="tiny muted" style="margin-top:9px">这些文件尚未生成，因此不提供假下载。</p>`,`<button class="btn" data-close>返回</button><button class="btn" id="exportReview">导出标注 PNG</button>${sample?'<button class="btn primary" id="openSplit">进入二维 / 三维分屏</button>':''}`);$('exportReview').onclick=exportOverlay;if($('openSplit'))$('openSplit').onclick=()=>{closeModal();closeDrawer();$('resultRibbon').classList.add('hidden');modelOpen=true;$('modelArea').classList.remove('hidden');updateUI();requestAnimationFrame(()=>{resize();fitView();drawModel()})}})}
function exportOverlay(){if(!asset())return;const a=asset(),c=document.createElement('canvas');c.width=a.width;c.height=a.height;const ctx=c.getContext('2d');ctx.drawImage(image,0,0,a.width,a.height);for(const o of floor().items){ctx.strokeStyle=color(o);ctx.lineWidth=1.5;ctx.strokeRect(...o.rect);ctx.font='12px sans-serif';ctx.fillStyle='white';const text=o.label||o.type;ctx.fillRect(o.rect[0],Math.max(0,o.rect[1]-20),ctx.measureText(text).width+8,18);ctx.fillStyle=color(o);ctx.fillText(text,o.rect[0]+4,Math.max(13,o.rect[1]-6))}c.toBlob(b=>{download(b,`P3_${floor().label}_${head().id}_复核标注_非建筑交付.png`);toast('已导出原图叠加标注；不是生成的二维图纸。')},'image/png')}
function help(){modal('更少面板，把注意力留给图纸。','这版 P3 沿用 P2 的视觉语言，重新组织信息出现的时机。',`<div class="help-rows"><div><b>项目</b><p>项目首页只负责选择。进入后用左上角返回或项目名切换，不常驻项目列表。</p></div><div><b>画布</b><p><kbd>V</kbd> 选择 <kbd>R</kbd> 补框 <kbd>H</kbd> 平移 <kbd>F</kbd> 适应<br>滚轮缩放；空格拖动；<kbd>O</kbd> 隐藏框看原图。</p></div><div><b>补框</b><p>拖动框选后才出现表单。角点调整大小，框内拖动位置；保存才产生版本。<kbd>Esc</kbd> 取消未保存编辑。</p></div><div><b>版本</b><p><kbd>⌘/Ctrl Z</kbd> 撤销，<kbd>⌘/Ctrl Shift Z</kbd> 重做。历史按需打开；恢复追加新版本，不删历史。</p></div><div><b>生成</b><p>确认快照后演示分阶段进度，可收起或取消。更改标注后，旧成果过期。实际模型与 BIMFACE 均未连接。</p></div><div><b>数据</b><p>1F 使用你提供的 P2 原型内嵌图；2F/3F 为程序绘制示例，楼层分配只用于交互。识别框是预设，不是检测结果。</p></div></div><div class="notice amber" style="margin-top:17px">本页支持真实图片导入、框选、撤销、历史、浏览器保存和标注导出；不恢复真实尺寸、不输出 DXF/PDF/GLB，不自动识图，也不重建你的建筑。</div>`,`<button class="btn primary" data-close>回到画布</button>`,true)}
